// Use constants instead of string literals:
@GetMapping(
    value = "/users",
    produces = MediaType.APPLICATION_JSON_VALUE  // "application/json"
)

@PostMapping(
    value = "/upload",
    consumes = MediaType.MULTIPART_FORM_DATA_VALUE  // "multipart/form-data"
)

// In HttpHeaders:
HttpHeaders headers = new HttpHeaders();
headers.setContentType(MediaType.APPLICATION_JSON);
// Note: MediaType.APPLICATION_JSON is the MediaType object;
//       APPLICATION_JSON_VALUE is the String
